package com.oms.channel.platform;

import com.ruoyi.common.core.domain.R;
import org.junit.jupiter.api.*;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.jdbc.datasource.*;
import java.time.*;
import java.util.*;
import java.util.concurrent.atomic.AtomicBoolean;
import static org.junit.jupiter.api.Assertions.*;
import static org.mockito.Mockito.*;
import static org.mockito.ArgumentMatchers.*;
import static com.oms.channel.platform.ChannelPlatformService.map;

class PlatformLogTest {
    PlatformInteractionLog logs;PlatformLogQuery query;JdbcTemplate db;PlatformLogBusinessClient business;
    @BeforeEach void setup(){String url=System.getenv("CHANNEL_TEST_URL");assertNotNull(url);assertTrue(url.contains("/channel_platform_test?"));DriverManagerDataSource source=new DriverManagerDataSource(url,"root",System.getenv("INVENTORY_TEST_PASSWORD"));db=new JdbcTemplate(source);for(String table:Arrays.asList("channel_interaction_payload","channel_interaction_business_link","channel_interaction_log","t_channel"))db.update("DELETE FROM "+table);db.update("INSERT INTO t_channel(channel_id,channel_name,channel_type,enabled,to_channel_enabled,sync_enabled,m_model_type,company_code) VALUES (101,'本公司','TM',1,1,0,1,'QM'),(102,'其他公司','TM',1,1,0,1,'OTHER')");logs=new PlatformInteractionLog();logs.db=db;logs.transactionManager=new DataSourceTransactionManager(source);query=new PlatformLogQuery();query.logs=logs;business=mock(PlatformLogBusinessClient.class);query.business=business;when(business.resolve(anyString(),anyMap(),anyString())).thenReturn(R.ok(Collections.emptyList()));when(business.states(anyString(),anyList(),anyString())).thenReturn(R.ok(Collections.emptyList()));TmallClient.clearTransport();}
    @AfterEach void clean(){TmallClient.clearTransport();}
    Map<String,Object> begin(String company,String kind){return logs.begin(company,101L,null,"tmall.exchange.get",kind,"REAL","EXCHANGE","tester",map("interface_name","tmall.exchange.get","refs",Collections.singletonList(map("type","PLATFORM_EXCHANGE","number","123456"))),map("dispute_id","123456"));}
    @SuppressWarnings("unchecked") List<Map<String,Object>> rows(Map<String,String> filter){return (List<Map<String,Object>>)query.list("QM",filter).get("rows");}
    Map<String,String> input(String... pairs){Map<String,String> m=new HashMap<>();for(int i=0;i<pairs.length;i+=2)m.put(pairs[i],pairs[i+1]);return m;}
    @Test void localRefundSyncHasItsOwnCategoryAndImmutableSearchLinks(){com.oms.channel.controller.PlatformLogController controller=new com.oms.channel.controller.PlatformLogController();org.springframework.test.util.ReflectionTestUtils.setField(controller,"logs",logs);org.springframework.test.util.ReflectionTestUtils.setField(controller,"query",query);Map<String,Object> input=map("channel_id",101,"task_id",1,"mode","IDS","actor","tester");Map<String,Object> log=controller.refundSync("QM",input).getData();Map<String,Object> finish=new LinkedHashMap<>(log);finish.putAll(map("result","SUCCESS","records",1,"refs",Collections.singletonList(map("type","PLATFORM_REFUND","number","9007199254740993"))));controller.refundSyncFinish("QM",finish);Map<String,Object> row=rows(input("category","REFUND","numberType","PLATFORM_REFUND","number","9007199254740993","allTime","true")).get(0);assertEquals("LOCAL",row.get("environment"));assertEquals("DATA_SYNC",row.get("entry_kind"));assertEquals(0,((Number)row.get("request_sent")).intValue());assertNull(row.get("http_status"));finish.put("refs",Collections.singletonList(map("type","PLATFORM_REFUND","number","9007199254740994")));controller.refundSyncFinish("QM",finish);assertEquals(0,rows(input("numberType","PLATFORM_REFUND","number","9007199254740994","allTime","true")).size());assertThrows(IllegalArgumentException.class,()->controller.refundSync("OTHER",input));assertThrows(IllegalArgumentException.class,()->controller.refundSyncFinish("OTHER",finish));}
    @Test void companyIdentityIsNormalizedWithoutAcceptingAnotherTenant(){db.update("UPDATE t_channel SET company_code='qm' WHERE channel_id=101");assertEquals("QM",logs.companyForShop("QM",101));assertThrows(IllegalArgumentException.class,()->logs.companyForShop("OTHER",101));Map<String,Object> log=begin("qm","API");assertEquals("QM",log.get("company_code"));assertEquals(1,rows(Collections.emptyMap()).size());}
    @Test void completedAttemptIsImmutableAfterLaterQuery(){Map<String,Object> old=begin("QM","API");logs.finish(old,"UNKNOWN","TIMEOUT",map("error_code","TIMEOUT"),10,null,true);Map<String,Object> context=new LinkedHashMap<>(old);context.put("parent_request_id",old.get("request_id"));Map<String,Object> check=logs.begin("QM",101L,null,"tmall.exchange.get","API","REAL","EXCHANGE","tester",context,Collections.emptyMap());logs.finish(check,"SUCCESS","",map("status","12"),20,200,true);logs.finish(old,"SUCCESS","",map("status","12"),50,200,true);assertEquals("UNKNOWN",query.detail("QM",((Number)old.get("id")).longValue()).get("result"));assertEquals("SUCCESS",query.detail("QM",((Number)check.get("id")).longValue()).get("result"));assertEquals(2,((List<?>)query.detail("QM",((Number)old.get("id")).longValue()).get("chain")).size());}
    @Test void tenantScopeAppliesToListDetailPayloadAndLinkLookup(){Map<String,Object> own=begin("QM","API");begin("OTHER","API");assertEquals(1,rows(Collections.emptyMap()).size());long id=((Number)own.get("id")).longValue();assertThrows(IllegalArgumentException.class,()->query.detail("OTHER",id));assertThrows(IllegalArgumentException.class,()->query.payload("OTHER",id));assertEquals(1,rows(input("numberType","PLATFORM_EXCHANGE","number","123456","allTime","true")).size());}
    @Test void httpSuccessWithBusinessRejectionIsFailure(){Map<String,Object> parent=begin("QM","OPERATION");try(PlatformInteractionLog.Scope ignored=logs.scope(parent)){assertThrows(TmallClient.Failure.class,()->logs.call("tmall.exchange.agree",map("dispute_id","123456"),()->{TmallClient.transport().httpStatus=200;TmallClient.transport().sent=true;throw new TmallClient.Failure("ISV_DENIED",false);}));}Map<String,Object> child=rows(input("entryKind","API")).get(0);assertEquals("FAILED",child.get("result"));assertEquals(200,child.get("http_status"));assertEquals("ISV_DENIED",child.get("error_code"));}
    @Test void missingContextPreventsExecutionAndThreadScopeIsRestored(){AtomicBoolean called=new AtomicBoolean();assertThrows(IllegalArgumentException.class,()->logs.call("x",Collections.emptyMap(),()->{called.set(true);return null;}));assertFalse(called.get());Map<String,Object> parent=begin("QM","OPERATION");try(PlatformInteractionLog.Scope ignored=logs.scope(parent)){logs.call("tmall.exchange.get",Collections.emptyMap(),()->map("dispute_id","123456"));}assertThrows(IllegalArgumentException.class,()->logs.call("x",Collections.emptyMap(),()->null));}
    @Test void cursorDoesNotRepeatRowsWhenNewCallsArrive(){begin("QM","API");begin("QM","API");begin("QM","API");Map<String,Object> first=query.list("QM",input("limit","2"));String cursor=String.valueOf(first.get("next_cursor"));assertFalse(cursor.isEmpty());begin("QM","API");List<Map<String,Object>> next=rows(input("limit","2","cursor",cursor));assertEquals(1,next.size());assertEquals(4,rows(Collections.emptyMap()).size());}
    @Test void rangeAndExactNumberBoundariesRejectExpensiveOrInvalidRequests(){assertThrows(IllegalArgumentException.class,()->rows(input("allTime","true")));assertThrows(IllegalArgumentException.class,()->rows(input("limit","101")));assertThrows(IllegalArgumentException.class,()->rows(input("numberType","EXCHANGE","number","' OR 1=1")));assertThrows(IllegalArgumentException.class,()->rows(input("start","2026-01-01 00:00:00","end","2026-03-01 00:00:00")));assertThrows(IllegalArgumentException.class,()->rows(input("cursor","bad|oops")));verifyNoInteractions(business);}
    @Test void staleUnfinishedAttemptIsUnknownWithoutChangingOriginalRecord(){Map<String,Object> log=begin("QM","API");db.update("UPDATE channel_interaction_log SET create_time=DATE_SUB(NOW(),INTERVAL 2 MINUTE) WHERE id=?",log.get("id"));assertEquals("UNKNOWN",rows(Collections.emptyMap()).get(0).get("result"));assertEquals(1L,query.summary("QM",Collections.emptyMap()).get("UNKNOWN"));assertEquals("RUNNING",db.queryForObject("SELECT result FROM channel_interaction_log",String.class));}
    @Test void payloadExpirationDoesNotHideSummaryAndPurgeIsTenantScoped(){Map<String,Object> own=begin("QM","API"),other=begin("OTHER","API");db.update("UPDATE channel_interaction_payload SET create_time=DATE_SUB(NOW(),INTERVAL 15 DAY)");assertEquals(true,query.payload("QM",((Number)own.get("id")).longValue()).get("expired"));assertEquals(1,rows(Collections.emptyMap()).size());logs.purge("QM");assertEquals(1,db.queryForObject("SELECT COUNT(*) FROM channel_interaction_payload WHERE company_code='OTHER'",Integer.class));db.update("UPDATE channel_interaction_log SET create_time=DATE_SUB(NOW(),INTERVAL 91 DAY) WHERE id=?",own.get("id"));assertEquals(1,logs.purge("QM"));assertThrows(IllegalArgumentException.class,()->query.detail("QM",((Number)own.get("id")).longValue()));assertNotNull(query.detail("OTHER",((Number)other.get("id")).longValue()));}
    @Test void snapshotsDoNotExposeCredentialsNestedPiiOrUnknownFreeText(){Map<String,Object> response=map("access_token","PRIVATE_ACCESS","refresh_token","PRIVATE_REFRESH","request_id","echo_PRIVATE_ACCESS","data",map("mobile","13812345678","name","真实姓名","complete_address","私人地址","unknown_message","PRIVATE_UNSAFE","success",true));String body=PlatformLogSanitizer.snapshot(response).json;for(String forbidden:Arrays.asList("PRIVATE_ACCESS","PRIVATE_REFRESH","13812345678","真实姓名","私人地址","PRIVATE_UNSAFE"))assertFalse(body.contains(forbidden),forbidden);assertTrue(body.contains("已脱敏"));assertTrue(body.contains("success"));assertTrue(body.contains("true"));String echo=PlatformLogSanitizer.snapshot(map("request_id","echo_PRIVATE_SESSION"),Collections.singleton("PRIVATE_SESSION")).json;assertFalse(echo.contains("PRIVATE_SESSION"));}
    @Test void oversizedArraysAndBodiesAreExplicitlyTruncated(){List<Map<String,Object>> records=new ArrayList<>();for(int i=0;i<60;i++)records.add(map("dispute_id",i+1));PlatformLogSanitizer.Snapshot snapshot=PlatformLogSanitizer.snapshot(map("records",records));assertTrue(snapshot.truncated);assertFalse(snapshot.json.contains("\"dispute_id\":60"));}
    @Test void listNeverReturnsPayloadAndProgressFailureDoesNotChangeAttempt(){Map<String,Object> own=begin("QM","API");logs.finish(own,"SUCCESS","",map("dispute_id","123456"),1,200,true);Map<String,Object> row=rows(Collections.emptyMap()).get(0);assertFalse(row.containsKey("request_json"));assertFalse(row.containsKey("response_json"));when(business.states(anyString(),anyList(),anyString())).thenThrow(new RuntimeException("PRIVATE_FAILURE"));assertEquals(false,query.states("QM",Collections.singletonList(map("type","EXCHANGE","number","HH1"))).get("available"));assertEquals("SUCCESS",rows(Collections.emptyMap()).get(0).get("result"));}
    @Test void responseIdsCreateSearchLinksWithoutParsingPayloadOnRead(){Map<String,Object> own=begin("QM","API");logs.finish(own,"SUCCESS","",map("records",Collections.singletonList(map("dispute_id","98765","biz_order_id","9876501"))),1,200,true);assertEquals(1,rows(input("numberType","PLATFORM_EXCHANGE","number","98765","allTime","true")).size());assertEquals(1,rows(input("numberType","PLATFORM_OID","number","9876501","allTime","true")).size());}
    @Test void longTraceIncludesSelectedAttemptAndRecentResults(){Map<String,Object> old=begin("QM","OPERATION");for(int i=0;i<101;i++)logs.begin("QM",101L,null,"tmall.exchange.get","API","REAL","EXCHANGE","tester",map("root_request_id",old.get("root_request_id")),Collections.emptyMap());Map<String,Object> detail=query.detail("QM",((Number)old.get("id")).longValue());List<?> chain=(List<?>)detail.get("chain");assertEquals(true,detail.get("chain_truncated"));assertEquals(100,chain.size());assertTrue(chain.stream().anyMatch(value->Objects.equals(((Map<?,?>)value).get("id"),old.get("id"))));}
    @Test void platformRequestIdentifierIsReadFromTheActualResponseEnvelope(){Map<String,Object> log=begin("QM","API");logs.finish(log,"SUCCESS","",map("tmall_exchange_get_response",map("request_id","TOP_REQUEST_123","result",map("success",true))),1,200,true);assertEquals("TOP_REQUEST_123",query.detail("QM",((Number)log.get("id")).longValue()).get("platform_request_id"));}
    @Test void retentionDrainsMoreThanOneBatchWithoutTouchingAnotherCompany(){List<Object[]> values=new ArrayList<>();for(long id=1;id<=2100;id++)values.add(new Object[]{"QM",id});db.batchUpdate("INSERT INTO channel_interaction_payload(company_code,log_id,create_time) VALUES (?,?,DATE_SUB(NOW(),INTERVAL 15 DAY))",values);assertEquals(0,logs.purge("QM"));assertEquals(0,db.queryForObject("SELECT COUNT(*) FROM channel_interaction_payload",Integer.class));}
    @Test void automaticSearchMatchesDirectAndResolvedNumbersButRemainsTenantScoped(){begin("QM","API");begin("OTHER","API");when(business.resolve(eq("QM"),anyMap(),anyString())).thenReturn(R.ok(Collections.singletonList(map("type","PLATFORM_EXCHANGE","number","123456"))));assertEquals(1,rows(input("numberType","AUTO","number","HH_TEST","allTime","true")).size());assertEquals(1,rows(input("number","123456","allTime","true")).size());assertEquals(0,rows(input("numberType","AUTO","number","HH_TEST","method","tmall.exchange.consigngoods","allTime","true")).size());}
    @Test void businessContextCanExplainNonCallsWithoutInventingInteractionRows(){when(business.resolve(eq("QM"),anyMap(),anyString())).thenReturn(R.ok(Collections.singletonList(map("type","EXCHANGE","number","HH_TEST"))));when(business.states(eq("QM"),anyList(),anyString())).thenReturn(R.ok(Collections.singletonList(map("id",1,"source_kind","INTERNAL","exchange_sn","HH_TEST"))));Map<String,Object> context=query.context("QM",input("number","HH_TEST"));assertEquals(true,context.get("available"));assertEquals(1,((List<?>)context.get("rows")).size());assertEquals(0,db.queryForObject("SELECT COUNT(*) FROM channel_interaction_log",Integer.class));when(business.resolve(anyString(),anyMap(),anyString())).thenThrow(new RuntimeException("PRIVATE_FAILURE"));assertEquals(false,query.context("QM",input("number","HH_TEST")).get("available"));assertThrows(IllegalArgumentException.class,()->query.context("QM",input("number","' OR 1=1")));}
}
